 * into its low 64 bits. */
#define KS_EXP_ANY_BODY(W, ELEM, BYTES) \
    uint8x16_t v, all; \
    KS_EXP_ANY_REGISTERS_##W \
    uint32x4_t words = vreinterpretq_u32_u8(all); \
    return vgetq_lane_u64(vreinterpretq_u64_u32(vpmaxq_u32(words, words)), 0) != 0u;
