    memcpy(&v, ((const uint8_t *)&value) + offset, 16u); out |= KS_SSE_MOVEMASK_##BYTES(v) << shift;
#define KS_EXP_BITS_BODY(W, ELEM, BYTES) \
    uint64_t out = 0u; __m128i v; \
