#define KS_EXP_BITS_REGISTERS_16(BYTES) KS_EXP_BITS_REGISTER(BYTES, 0u, 0u)
#define KS_EXP_BITS_REGISTERS_32(BYTES) KS_EXP_BITS_REGISTER(BYTES, 0u, 0u) \
